draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a fruit
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw a stick figure eating the fruit
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 100, H/2 + 100); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 80, H/2 + 80); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 120, H/2 + 80); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100);
  ctx.lineTo(W/2 + 90, H/2 + 130); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100);
  ctx.lineTo(W/2 + 110, H/2 + 130); // leg
  ctx.stroke();

  // make the stick figure move up and down
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 90, H/2 + 130 + 20 * Math.sin(t)); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 110, H/2 + 130 + 20 * Math.sin(t)); // leg
  ctx.stroke();

  ctx.restore();
}
